<?php
class Materia{function __construct(private PDO $db){} function obtenerTodos($b=''){ $s=$this->db->prepare("SELECT * FROM materias WHERE clave LIKE ? OR nombre LIKE ? ORDER BY id DESC");$s->execute(["%$b%","%$b%"]);return $s->fetchAll();} function obtenerPorId($id){$s=$this->db->prepare("SELECT * FROM materias WHERE id=?");$s->execute([$id]);return $s->fetch()?:null;} function insertar($d){return $this->db->prepare("INSERT INTO materias(clave,nombre,creditos,semestre) VALUES(?,?,?,?)")->execute([$d['clave'],$d['nombre'],$d['creditos'],$d['semestre']]);} function actualizar($d){return $this->db->prepare("UPDATE materias SET clave=?,nombre=?,creditos=?,semestre=? WHERE id=?")->execute([$d['clave'],$d['nombre'],$d['creditos'],$d['semestre'],$d['id']]);} function eliminar($id){return $this->db->prepare("DELETE FROM materias WHERE id=?")->execute([$id]);}}